                quit_requested = 1;

            load_registered_texture_refs(1);
            g_game->InitLast();
            g_game_initialization_pending = 0;
            g_frame_render_requested = 0;
            g_loading_bar.UnInit();
            g_game->fade.StartOn();
            show_and_focus_game_window();
