    g_game->subgame.sub_high_score.MiniSave(2);
    g_game->subgame.sub_high_score.MiniSave(4);
    g_game->subgame.sub_high_score.MiniSave(8);
    g_game->subgame.sub_high_score.MiniSave(16);
